// MULTIROW (two-show fleet model, 2026-08-03): channel-preferred row selection with legacy fallback.
// PURPOSE: U13 standing pre-check verdict (Skill 58 Phase 2). Fail-closed: any
// ambiguity (lookup error, unknown identity, flipped NO row) resolves to
// good_standing:false. Never leaks roster data beyond {ok, good_standing, reason}.

const webhookJson = $('Webhook — Standing Check').first().json;
const body = webhookJson.body || webhookJson;
const lastName = (body.client_last_name || '').trim();
const email = (body.client_email || '').toLowerCase().trim();
const podcastId = body.podcast_id || '';

const inputItems = $input.all();
const lookupErrored = inputItems.length > 0 && inputItems[0].json && inputItems[0].json.error;
const rows = lookupErrored ? [] : inputItems.map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);

let good_standing = false;
let reason;

if (lookupErrored) {
  reason = 'lookup_error';
} else if (rows.length === 0) {
  reason = 'identity_unknown';
} else {
  const row = (podcastId ? rows.find(r => String(r.podbean_channel_id || '').trim() === podcastId) : null) || rows[0];
  if (String(row.good_standing || '').toUpperCase() !== 'YES') {
    reason = 'not_in_good_standing';
  } else {
    good_standing = true;
  }
}

const responseBody = { ok: true, good_standing };
if (reason) responseBody.reason = reason;

return [{
  json: {
    responseBody,
    ledgerRow: {
      idempotency_key: `precheck-${lastName}|${email}|${Date.now()}`,
      channel_id: podcastId,
      episode_number: 0,
      permalink_url: '',
      status: 'precheck',
      reason: reason || '',
      source: 'podcast-standing-check',
      completed_at: new Date().toISOString()
    }
  }
}];

// FLEET STANDING GATE (additional, layered on top of the existing podcast_publish_roster
// good-standing precheck computed by 'Code — Determine Standing Verdict', immediately above).
// Does NOT replace or weaken that check -- if it already failed, its exact reason passes
// through untouched. Only when it already PASSED does this node also require the newer
// fleet_standing table (id aoLFsegM1aDIrcDj): approved = (good_standing === true) &&
// (podcast_approved === true), good_standing OUTRANKING podcast_approved. Fail-closed:
// lookup error / unresolved identity / null columns all resolve to NOT approved, reason
// 'not_enrolled' (the safe default -- never guess 'standing' when unsure).
//
// fleet_standing has no email/last_name columns, only box_slug/client_label/aliases
// (pipe-delimited). This endpoint's payload carries client_email/client_last_name, so
// identity is resolved the same alias-matching way used in the main publish gate
// (TkL0rn2SH3q32SeB) and in system-access-rejection-notify (UqfhxcPqlB0aPgf5).

const oldResult = $('Code — Determine Standing Verdict').first().json; // {responseBody, ledgerRow}
const wh = $('Webhook — Standing Check').first().json;
const body = wh.body || wh;

// === SHARED IDENTITY NORMALISER (FIX-RESCUE-19, 2026-08-03) ================
// Reconciled with fleet-standing-check (hfSyTquUQ0SccMzD) so the fleet runs ONE
// normalisation rule instead of a per-workflow variant. Two changes vs the local
// norm() this replaces:
//   * PLACEHOLDER DENYLIST. A token an LLM or a seed script writes when it could
//     not resolve a real value ('TBD', 'unknown', 'n/a', 'none', '-') must never
//     function as an identifier. It previously did, and combined with the
//     substring match tier below that is a live cross-client hazard: a payload
//     carrying the literal 'NA' substring-matches any alias containing 'na', and
//     live roster aliases do contain it -- so this gate could read a DIFFERENT
//     person's good_standing / *_approved columns and decide from them.
//   * WHITESPACE COLLAPSE. 'van  dyke' and 'van dyke' are one name.
// readBool() also calls norm(); the denylist does not change any of its outcomes
// ('null'/'none'/'-' already returned null, and '0'/'1' are not placeholders).
// DELIBERATELY NOT CHANGED HERE: the substring match tier, and the fail-CLOSED
// direction. This node must stay fail-closed (refusing a publish is recoverable);
// fleet-standing-check must stay fail-OPEN (refusing a rescue is not). That
// divergence is intentional and is recorded in CAP-VECTORS-CLOSED.md -- do not
// "harmonise" it away.
const IDENT_PLACEHOLDERS = new Set(['', 'tbd', 'n/a', 'na', 'none', 'unknown', 'null', '-', '?', 'tba']);
const norm = (s) => {
  const n = String(s === null || s === undefined ? '' : s).trim().toLowerCase().replace(/\s+/g, ' ');
  return IDENT_PLACEHOLDERS.has(n) ? '' : n;
};
const lookupEmail = norm(body.client_email);
const lookupLastName = norm(body.client_last_name);

const rows = $input.all()
  .map((i) => (i && i.json) || null)
  .filter((r) => r && !r.error && typeof r === 'object' && ('box_slug' in r || 'client_label' in r));

function labelLastName(label) {
  const stripped = String(label || '').replace(/\s*\(.*$/, '').trim();
  const parts = stripped.split(/\s+/).filter(Boolean);
  return parts.length ? norm(parts[parts.length - 1]) : '';
}

const matches = rows.filter((r) => {
  const aliasTokens = norm(r.aliases).split('|').map((a) => a.trim()).filter(Boolean);
  const aliasExact = (!!lookupEmail && aliasTokens.includes(lookupEmail)) ||
                      (!!lookupLastName && aliasTokens.includes(lookupLastName));
  const aliasSubstring = !aliasExact && !!lookupLastName && aliasTokens.some((a) => a.includes(lookupLastName));
  const labelMatch = !!lookupLastName && labelLastName(r.client_label) === lookupLastName;
  return aliasExact || aliasSubstring || labelMatch;
});

// 2026-08-01 audit fix (INLINE-07): exact email-token match takes precedence over
// substring/label matches, so shared last names (e.g. 'Otts' matching 'Eddie Otts')
// no longer create false ambiguity. Still fail-closed: >1 exact email match remains ambiguous.
const exactEmailMatches = matches.filter((r) => {
  const t = norm(r.aliases).split('|').map((a) => a.trim()).filter(Boolean);
  return !!lookupEmail && t.includes(lookupEmail);
});
const resolvedMatches = exactEmailMatches.length > 0 ? exactEmailMatches : matches;
const matched = resolvedMatches.length === 1;
const person = matched ? resolvedMatches[0] : null;

function readBool(row, col) {
  if (!row || !Object.prototype.hasOwnProperty.call(row, col)) return null;
  const v = row[col];
  if (v === true) return true;
  if (v === false) return false;
  const n = norm(v);
  if (['true', 'yes', '1'].indexOf(n) !== -1) return true;
  if (['false', 'no', '0'].indexOf(n) !== -1) return false;
  return null;
}

const goodStanding = matched ? readBool(person, 'good_standing') : null;
const podcastApproved = matched ? readBool(person, 'podcast_approved') : null;
const fleetApproved = matched && goodStanding === true && podcastApproved === true;

let fleetReasonCode;
if (matched && goodStanding === false) {
  fleetReasonCode = 'standing';
} else {
  fleetReasonCode = 'not_enrolled';
}

const oldGoodStanding = !!(oldResult.responseBody && oldResult.responseBody.good_standing);
const oldReason = oldResult.responseBody ? oldResult.responseBody.reason : undefined;

// The fleet gate only has a say if the OLD gate already passed. If the old gate already
// failed, its reason passes through byte-for-byte -- this node never overrides it.
const fleetCausedRefusal = oldGoodStanding && !fleetApproved;

let finalGoodStanding, finalReason;
if (!oldGoodStanding) {
  finalGoodStanding = false;
  finalReason = oldReason;
} else if (!fleetApproved) {
  finalGoodStanding = false;
  finalReason = fleetReasonCode === 'standing' ? 'not_in_good_standing' : 'not_enrolled';
} else {
  finalGoodStanding = true;
  finalReason = undefined;
}

const responseBody = { ok: true, good_standing: finalGoodStanding };
if (finalReason) responseBody.reason = finalReason;

const ledgerRow = Object.assign({}, oldResult.ledgerRow, {
  reason: finalReason || ''
});

const notifyReason = matched
  ? ('podcast standing-check (fleet_standing): ' + fleetReasonCode)
  : ('podcast standing-check (fleet_standing): identity unresolved, match_count=' + matches.length);

return [{
  json: {
    responseBody,
    ledgerRow,
    fleet_caused_refusal: fleetCausedRefusal,
    fleet_box_slug: matched ? String(person.box_slug || '') : '',
    fleet_client_label: matched ? String(person.client_label || '') : '',
    fleet_client_email: body.client_email || '',
    fleet_gate_notify_reason: notifyReason,
    // FIX-RESCUE-19 diagnostic: see the note in TkL0rn2SH3q32SeB. 0 rows means
    // the roster read returned nothing and every client is being refused.
    fleet_roster_rows: rows.length
  }
}];
